-- Regulation extracted from the pasted text; totalPages is 0 because pagination was not supplied.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODExda5eb9e3552f$doc_reg_civil_service_employee_conduct_2065$CODExda5eb9e3552f$,$CODEx68229e5cdc98$The Regulation Concerning the Conduct of Employees of the Civil Service, 2065 B.S. (2009)$CODEx68229e5cdc98$,NULL,$CODEx7320e2b5d0b7$regulation$CODEx7320e2b5d0b7$,2065,2009,0,$CODExe320c11274a7$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "The Regulation Concerning the Conduct of Employees of the  Civil Service, 2065 B.S. (2009)\nDate of Publication in the Nepal Gazette\n2065/11/19 B.S. (March 2, 2009)\nIn exercise of the power conferred by Section 44 of the Good Governance (Management and Operation) Act, 2064 B.S. (2007), the Government of Nepal has, by virtue of Clause (c) of Sub-section (2) of Section 23 of the said Act, made these Rules.", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-1", "title": "Preliminary", "content": null, "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 1", "title": "Short Title and Commencement", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "These Rules may be called the\"Regulation Concerning the Conduct of Employees of the Civil Service,\n2065 B.S. (2008).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "This Regulation shall come into effect at once.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 2", "title": "Definitions", "content": "Unless the subject or context otherwise requires, in this Regulation,", "children": [{"tier": 3, "nodeType": "clause", "identifier": "(a)", "title": null, "content": "\"Employee of the Civil Service\" mean and include an employee working in the Civil Service in accordance with the\nCivil Service Act, 2049 B.S. (1992) and an employee working in the health service in accordance with the Health Services Act, 2053 B.S. (1996).", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(b)", "title": null, "content": "\"Family\" means and includes the husband, wife, son, unmarried daughter, adopted son, unmarried adopted daughter, father, mother or step mother living together with, to be looked after by, a Civil Servant and in the case of a male employee or unmarried female employee their grandfather, grandmother, and in the case of a married female employee her father-in-law and mother-in-law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(c)", "title": null, "content": "\"Office\" means any Ministry, Secretariat, Commission or Department of the Government of Nepal or any other government  agency or office there under wherein a Civil servant is working.", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-2", "title": "Provisions Relating to Official Conduct", "content": "", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 3", "title": "Official Status to be Maintained", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Civil Servant shall, in discharging his official duties, always keep in mind the larger interest of the nation and the people and subject oneself to the existing laws.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Civil Servant shall, while owing allegiance to the Nepal Nation and Government, always remain alert not to do or allow to do any act in such manner as to compromise the status or dignity of his or her service.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A Civil Servant shall always be positive and treat others in a polite and dignified manner for the sake of making his or her position and service dignified.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "A Civil Servant shall carry out his or her official duty in a prompt manner.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "In cases where there are separate conduct related provisions required to be followed by a serving Civil Servant, it shall be mandatory also to follow those provisions.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 4", "title": "Due and Uniform Treatment to be Given", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Civil Servant shall give due and uniform treatment to all without distinction as to caste, creed, religion, language, sex, age, political or social standing, geographical factors, political affinity, access or relation, physical\ncondition, marital status or any of these.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 5", "title": "Only Official Functions to be Performed During Office Hours", "content": "A Civil Servant shall perform only official functions in a designated place during office hours and he or she shall not, during office hours, engage oneself in personal or any other activity that is not related to a function of his or her office:\nProvided that nothing herein shall prevent from imparting trainings on a subject related to his or her profession or duty in a publicly run university or any academy or educational institution imparting trainings in the public sector if such act does not hamper the work of his or her office.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 6", "title": "Bar to misuse office Equipment and Facilities", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No Civil Servant shall use any machinery, equipment or other sources, materials and facilities meant for the purpose of the office for personal purpose and benefit.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No Civil Servant shall, except on the order of a competent authority, move any machinery, equipment or other materials and facilities meant for the purpose of the office or give any of these things to any other person for use.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "No Civil Servant shall misuse any right, power, privilege or facility acquired by him or her in his or her official capacity.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 7", "title": "Bar to disclose or misuse Information", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No Civil Servant shall disclose any information to anybody that is deemed to be confidential by the existing laws.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No Civil Servant shall disclose or use, for his or her personal or family benefit or the benefit of any other person, any information or notice that has come to his or her knowledge in his or her official capacity or in the course of discharging his or her duty or by any other means, regardless of whether or not such information or notice was\nmade available to him or her in his or her office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "No Civil Servant, other than an Office-in-Charge, Information Officer or Spokesperson, shall make public any information not yet released by his or her office:\nProvided that nothing herein shall prevent from giving information that has already been made public by his or her office.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "While giving information to the public or to a person or civil servant in connection with the function of the office by an office, it is mandatory to give full and true information.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "No Civil Servant shall use any information acquired in the discharge of his or her official duties for any purpose other than the one for which such information was meant or made available.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(6)", "title": null, "content": "No Civil Servant, other than an Office-in-Charge, information officer or Spokesperson, shall without authorization, deliver a statement, give an interview or give information through any means of communication on any business of the office or any subject related thereto regardless of whether or not it is done on the condition of\nanonymity. In giving such information or delivering such a statement or granting such an interview upon getting authorization, one should limit oneself to the facts and no personal view or opinion may be expressed on that.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 8", "title": "Maintenance of Fairness in Official Duties", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Civil Servant shall discharge his or her official responsibility in a free and fair manner without being influenced by any undue influence, greed, pressure, recommendation of anybody or without prejudice and biasness to  anybody and without influenced by any consideration.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No Civil Servant shall do any business dealing with anybody or institution that has something to do with the business of his or her office or to accept or take any present, gift, donation from any person or institution in such manner as to affect his or her official duties and shall not engage oneself, directly or indirectly, in raising donation, gift or funding for whatever purpose.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 9", "title": "Prohibition on engaging in Trade and Commercial Activities", "content": "Except as permitted by the existing law, no Civil servant shall, individually or jointly in collaboration with any person or group, engage in any trade and commercial activities regardless of whether such activities are carried out\ndirectly or indirectly.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 10", "title": "Necessity to give information on matters of interest", "content": "In cases where a Civil Servant has any personal interest in any matter relating to his or her office, such employee shall be required to inform the higher authority about the same.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 11", "title": "Necessity to wear Identification Card, Dress", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Civil Servant shall, while on duty, wear his or her identification card conspicuously.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Civil Servant shall wear an eloquent dress.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "If any uniform has been prescribed for civil servants of a particular office, they shall wear such uniform on duty when they are in office and also during when they represent their office.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 12", "title": "Political Neutrality to be Maintained", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "No Civil Servant shall engage in any activity that may promote any personal, commercial or political will of any political officials.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No Civil Servant shall express any opinion in favour of or against any political party, its sister organizations or its leader nor shall a Civil Servant influence any of these in order to support or oppose. In matters of Trade Unions, it shall be dealt with as set forth in the relevant Act.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A Civil Servant shall, while discharging his or her official duty, maintain political neutrality to the fullest extent.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 13", "title": "Transparency to be Maintained", "content": "A Civil Servant shall make transparent any service to be provided, supply or goods to be delivered by his or her office or the proceeding and the decision making process in the case of carrying out construction works.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 14", "title": "Service Delivery", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Civil Servant shall always endeavor to carry out any responsibility entrusted to him or her in a quick, prompt, perfect and qualitative manner.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Civil Servant shall, while delivering service, give priority to the aged, the handicapped, the dismembered, a woman who has recently given birth to a child, or a pregnant woman, children and the helpless.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A Civil Servant shall deliver service to his or her client on time if, for any reason, service cannot be delivered on time or if a service intended by a client is not possible to deliver, he or she shall inform the client the ground and reason thereof as soon as possible.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(4)", "title": null, "content": "A Civil Service shall facilitate the public to have easy and direct access to the government or public service and shall, as far as practicable, give information and advice in a simple and plain language.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(5)", "title": null, "content": "If any information or particular of an agency of the Government of Nepal is required in the course of delivering service to any client, the service providing employee shall arrange to ask for such information or particular through his or her office.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 15", "title": "Grievance Handling", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Civil servant shall be required to be sensitive all the time towards any grievance of citizens in matters of the\nservices delivered by his or her office in such manner as to have less grievance as far as possible.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Civil Servant shall respond to any information sought or grievance made or application made by a person in respect of any activity or business of his or her office in an appropriate and effective manner and with due respect and on time, and a Civil Servant acting as the Chief of the respective office shall make arrangements in such\nmanner as to handle such grievance appropriately and effectively in a timely manner.", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-3", "title": "Provisions Relating to Professional Ethics", "content": "", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 16", "title": "Knowledge of Law and Compliance", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Civil Servant shall have, as a minimum, the knowledge of all the laws that are pertinent to his or her\nwork.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Civil Servant shall always respect and observe the existing laws, decisions or orders of courts and decisions of the constitutional bodies and the Government of Nepal.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 17", "title": "Necessity to respect the Profession", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A Civil Servant shall always make efforts to make his or her profession reputed and dignified by paying respect to the profession.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No expression shall be made or any information be released to the clients and the general public in such manner as to develop negative attitude towards the Civil Service.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 18", "title": "Making Efforts to develop one’s capacity", "content": "A Civil Servant shall always make efforts to develop his or her professional capacity while at  the same time discharging his or her official duties.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 19", "title": "Necessity to observe the conditions of professional License", "content": "In cases where a Civil Servant is required to obtain a license to discharge his or her official duties, such a civil servant shall observe the conditions of the license.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 20", "title": "Necessity to perform qualitatively", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A civil servant shall perform an entrusted responsibility in an honest manner and to the best of his or her\nability and quality.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "A Civil Servant shall take responsibility for any act performed by him or her provided that no action may be taken against him or her in respect of acts performed in accordance with the law.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A civil servant shall, while giving advice to the Government of Nepal or any other entity, do so on any subject where advice has been sought in such manner as to be compatible with the law in a fair and honest manner.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 21", "title": "Observance of Professional Guidelines", "content": "Ethical Guidelines existing in any particular profession or job shall also be required to be observed by a civil servant working in that profession or sector.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 22", "title": "Instructions to be followed", "content": "A civil servant shall follow instructions of higher authorities given in connection with the official business of the\nGovernment or the Office in a prompt manner.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 23", "title": "Financial Discipline and Maintenance of Ethics", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A civil Servant shall perform his function with economy.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No civil servant or a member of his or her family shall pocket or cause to pocket, abandon or misuse or cause to misuse any  government fund or government or public property.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "No civil servant shall allow any political party or sister organization of political party or for any programme of such party or its sister organization to use any government or public property in an unauthorized manner.", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-4", "title": null, "content": null, "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 24", "title": "Not to be deemed to have acted in breach of conduct", "content": "Notwithstanding anything contained elsewhere in this Regulation, the following acts shall not be deemed a violation of any conduct of this Regulation.", "children": [{"tier": 3, "nodeType": "clause", "identifier": "(a)", "title": null, "content": "To give a written or oral speech in his or her area of expertise and do study or teaching with prior approval if such acts are done outside office hours and without prejudice to the functioning of the office,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(b)", "title": null, "content": "To become a member of a professional or social institution relating to literature, art, culture, sports, knowledge science and technology and to participate in such forums,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(c)", "title": null, "content": "To participate, outside office hours, in meetings or seminars organized by professional unions and associations other than those organized by political parties or their sister organizations,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(d)", "title": null, "content": "To publish articles, write ups in such manner as not to make adverse effect on the policy, objectives, programmes, functioning and secrecy of the Government,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(e)", "title": null, "content": "To participate in a competition opened to all and to accept a prize, medal, certificate or commendation,", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(f)", "title": null, "content": "To initiate necessary proceedings in offices or courts to get remedy as an aggrieved party in accordance with the laws.", "children": []}]}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-5", "title": "Miscellaneous", "content": "", "children": [{"tier": 2, "nodeType": "rule", "identifier": "Rule 25", "title": "Personal Conduct", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A civil servant shall display due courtesy and respect towards higher authorities and behave oneself duly with\nsubordinate staff.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "No civil servant shall engage in gambling, playing cards and consume alcohol in public places or shall not do anything or display any behavior that may be deplorable in society.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(3)", "title": null, "content": "A civil servant shall always make efforts to enhance the faith of the public in the Government of Nepal and the Civil Service.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 26", "title": "Duty to notify", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "If a civil servant comes to know or gets information to the effect that a person has committed or about to commit any act to harm or damage any government or public property, he or she, if it falls within his or her authority, shall make appropriate arrangement to protect the property in question and if the matter falls within the jurisdiction of some other entity or body, he or she shall inform the in Charge of such entity or office of the incident forthwith.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "In cases where a Civil Servant gets information to the effect that somebody is about to commit or is committing any unlawful act or criminal act, he or she shall, forthwith, inform the entity concerned or his or her Office In-Charge.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 27", "title": "Power to make Extra code of conduct as per the nature of Work", "content": "Ministries or Secretaries and their subordinate agencies performing different nature of functions shall have the power to make and enforce extra code of conduct in accordance with the nature of their work.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 28", "title": "Duty of Retired Employee to observe", "content": null, "children": [{"tier": 3, "nodeType": "clause", "identifier": "(1)", "title": null, "content": "A retired Civil Servant shall as well observe the provisions contained in Rules 3,7,17, and 26 of this\nRegulation.", "children": []}, {"tier": 3, "nodeType": "clause", "identifier": "(2)", "title": null, "content": "It will not be allowed to disclose or cause to disclose, in any manner, any unpublished information that had come to his or her knowledge in the course of discharging official duties during when he or she was in service even after his or her retirement.", "children": []}]}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 29", "title": "Provision relating to Follow-up", "content": "Each and every Ministry, Secretariat, Commission or other central-level agency, shall on a regular basis,\nfollow up on whether or not an employee working in or under it, has followed the provisions of this Regulation and make arrangements to take departmental actions against violators in accordance with the\nexisting laws.", "children": []}, {"tier": 2, "nodeType": "rule", "identifier": "Rule 30", "title": "Dissemination of the Regulation", "content": "After the commencement of this Regulation, offices shall disseminate the provisions of this Regulation among their staffs.", "children": []}]}]$CODExe320c11274a7$::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,"originalTitle"=EXCLUDED."originalTitle","documentType"=EXCLUDED."documentType","yearBs"=EXCLUDED."yearBs","yearAd"=EXCLUDED."yearAd","totalPages"=EXCLUDED."totalPages",nodes=EXCLUDED.nodes;
